import{_ as t,o as i,c as s,ag as e}from"./chunks/framework.NIGIbcGl.js";const u=JSON.parse('{"title":"Mitra Registration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"customer/mitra-registration/index.md","filePath":"customer/mitra-registration/index.md"}'),n={name:"customer/mitra-registration/index.md"};function o(r,a,d,p,l,h){return i(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="mitra-registration-guide" tabindex="-1">Mitra Registration Guide <a class="header-anchor" href="#mitra-registration-guide" aria-label="Permalink to &quot;Mitra Registration Guide&quot;">​</a></h1><p>Self-serve onboarding for <strong>Mitra</strong> (partner) applicants. A mitra registers, uploads documents, and — once an admin approves — is issued a per-tier registration number (<code>MS.</code> / <code>MG.</code>), an Organization, a SAR wallet, and the pricing access flags for their tier.</p><blockquote><p><strong>Mitra vs B2B vs Partner.</strong> Mitra is a <strong>customer-onboarding</strong> flow, distinct from the admin-provisioned banking <strong>Partner</strong> API-key module and from the <strong>B2B</strong> KYC flow (which requires NIB/NPWP). Individuals with no company documents can register as mitra.</p></blockquote><hr><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Prefix</th><th>On approval</th></tr></thead><tbody><tr><td>Mitra Silver</td><td><code>MS.</code></td><td>Promo pricing access</td></tr><tr><td>Mitra Gold</td><td><code>MG.</code></td><td>Promo + special-B2B pricing access</td></tr></tbody></table><p><strong>Who can apply:</strong> <code>COMPANY</code> (with company name/address) or <code>INDIVIDUAL</code> applicants. <code>INDIVIDUAL</code> applicants must additionally upload a KTP and receive an organization-of-one on approval.</p><hr><h2 id="required-documents" tabindex="-1">Required Documents <a class="header-anchor" href="#required-documents" aria-label="Permalink to &quot;Required Documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Required for</th><th>Accepted types</th></tr></thead><tbody><tr><td>SPK</td><td>All applicants</td><td>PDF, DOCX</td></tr><tr><td>KTP</td><td><code>INDIVIDUAL</code> only</td><td>JPEG, PNG, WebP, PDF</td></tr><tr><td>Partnership file</td><td>All applicants</td><td>PDF, DOCX, JPEG, PNG, WebP</td></tr><tr><td>Payment proof</td><td><code>SILVER</code> (100 SAR)</td><td>PDF, JPEG, PNG, WebP</td></tr></tbody></table><p>Max upload size: 10 MB per file.</p><blockquote><p>The <strong>Gold 50,000 SAR deposit</strong> is handled outside this flow (a separate deposit process) and is not captured here.</p></blockquote><hr><h2 id="api-endpoints" tabindex="-1">API Endpoints <a class="header-anchor" href="#api-endpoints" aria-label="Permalink to &quot;API Endpoints&quot;">​</a></h2><h3 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;host&gt;/api/v1</span></span></code></pre></div><h3 id="_1-submit-a-registration" tabindex="-1">1. Submit a registration <a class="header-anchor" href="#_1-submit-a-registration" aria-label="Permalink to &quot;1. Submit a registration&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>POST /auth/mitra/register</code></p><p><strong>Authentication:</strong> Optional. Unauthenticated submissions resolve or create a passwordless account from the applicant email/phone (login later via OTP).</p><p><strong>Request Body:</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SILVER&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;COMPANY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Budi Santoso&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantEmail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;budi@example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantPhone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;+6281234567890&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;companyName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PT Mitra Sejahtera&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;companyAddress&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Jl. Merdeka No. 1, Jakarta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;spkNumber&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;05.123/ADI/07/2026&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>spkNumber</code> is optional but, when supplied, must match <code>05.XXX/ADI/MM/YYYY</code>.</li><li><code>companyName</code> / <code>companyAddress</code> apply to <code>COMPANY</code> applicants.</li></ul><p><strong>Response:</strong> <code>201 Created</code> — the created registration (<code>status: &quot;PENDING&quot;</code>).</p><h3 id="_2-upload-a-document" tabindex="-1">2. Upload a document <a class="header-anchor" href="#_2-upload-a-document" aria-label="Permalink to &quot;2. Upload a document&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>POST /auth/mitra/register/:id/upload/:docType</code></p><p><code>docType ∈ { spk, ktp, partnership, payment-proof }</code>. Multipart form field <code>file</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/auth/mitra/register/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/upload/spk&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;file=@SPK.pdf&quot;</span></span></code></pre></div><p><strong>Response:</strong> <code>201 Created</code> — the updated registration with the document linked.</p><blockquote><p>If the registration already carries a valid <code>spkNumber</code>, the uploaded SPK&#39;s display filename is set to the number (e.g. <code>05.123_ADI_07_2026.pdf</code>).</p></blockquote><h3 id="_3-check-registration-status" tabindex="-1">3. Check registration status <a class="header-anchor" href="#_3-check-registration-status" aria-label="Permalink to &quot;3. Check registration status&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>GET /auth/mitra/application/status</code></p><p><strong>Authentication:</strong> Bearer JWT (the applicant&#39;s account).</p><p><strong>Response:</strong> <code>200 OK</code> — the applicant&#39;s latest registration record.</p><hr><h2 id="post-approval" tabindex="-1">Post-Approval <a class="header-anchor" href="#post-approval" aria-label="Permalink to &quot;Post-Approval&quot;">​</a></h2><p>On approval an admin issues:</p><ul><li>a per-tier <strong>registration number</strong> (<code>MS.001</code> … <code>MS.999</code> … <code>MS.1000</code>, likewise <code>MG.</code>),</li><li>an <strong>Organization</strong> + <strong>SAR Wallet</strong>,</li><li>the tier&#39;s pricing flags (Gold ⇒ special + promo; Silver ⇒ promo), and</li><li>the applicant account is promoted to a B2B organization member.</li></ul><p>An approval email is sent to the applicant.</p><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/ahlaan-train-docs/customer/register-login/">Registration &amp; Login</a></li><li><a href="/ahlaan-train-docs/customer/b2b-registration/">B2B Registration Guide</a></li></ul>`,41)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
